        print("case 3 buckets after", collide.bucketCount(), 8);
        print("case 3 gets survive rehash",
                collide.get(1) + "/" + collide.get(5) + "/"
                        + collide.get(9) + "/" + collide.get(13),
                "10/50/90/130");
